select SEQNO, BOK_SEQNO, BOOKSET_ID, HAPPEN_DATE, BOOK_DATE, BOOKSET_DATE, BOK_DETAIL_ID, BUSI_ID, SCHEME_DETAIL_ID, TRADE_ID, LOSS_EXE_TYPE, LOSS_GEN_TYPE, CCY, B_CCY, TDY_COST_AMT, TDY_INT_AMT, TDY_LOSSAMT_ADD, TDY_LOSSAMT, TDY_LOSSAMT_ADD_B, TDY_LOSSAMT_B from (SELECT SEQNO, BOK_SEQNO, BOOKSET_ID, HAPPEN_DATE, BOOK_DATE, BOOKSET_DATE, BOK_DETAIL_ID, BUSI_ID, SCHEME_DETAIL_ID, TRADE_ID, LOSS_EXE_TYPE, LOSS_GEN_TYPE, CCY, B_CCY, TDY_COST_AMT, TDY_INT_AMT, TDY_LOSSAMT_ADD, TDY_LOSSAMT, TDY_LOSSAMT_ADD_B, TDY_LOSSAMT_B, rownum AS rn FROM (SELECT ROW_NUMBER() OVER(PARTITION BY bc.BOOK_ID ORDER BY bc.BOOK_ORDER DESC ) AS rn, bp.SEQNO, bp.BOK_SEQNO, bp.BOOKSET_ID, bp.HAPPEN_DATE, bp.BOOK_DATE, bp.BOOKSET_DATE, bp.BOK_DETAIL_ID, bp.BUSI_ID, bp.SCHEME_DETAIL_ID, bp.TRADE_ID, bp.LOSS_EXE_TYPE, bp.LOSS_GEN_TYPE, bp.CCY, bp.B_CCY, bp.TDY_COST_AMT, bp.TDY_INT_AMT, bp.TDY_LOSSAMT_ADD, bp.TDY_LOSSAMT, bp.TDY_LOSSAMT_ADD_B, bp.TDY_LOSSAMT_B FROM BOK_STAT_LOSS_POSIITON bp LEFT JOIN BOK_BOOKDETAIL_CURRENT bc ON bp.BOK_SEQNO = bc.SEQNO WHERE 1 =1 AND bp.BOOKSET_ID = #{booksetId}
AND bp.BUSI_ID = #{busiId}
AND bp.HAPPEN_DATE >= #{happenDateSta}
AND bp.HAPPEN_DATE <= #{happenDateEnd}
AND bp.HAPPEN_DATE = #{happenDate}
AND bp.BOOK_DATE <= #{bookDate}
AND bc.BOK_DETAIL_ID = #{bokDetailId}
AND bp.LOSS_GEN_TYPE = #{lossGenType}
) where rn = 1 ORDER BY HAPPEN_DATE desc ) WHERE RN = 1

select SEQNO, BOK_SEQNO, BOOKSET_ID, HAPPEN_DATE, BOOK_DATE, BOOKSET_DATE, BOK_DETAIL_ID, BUSI_ID, SCHEME_DETAIL_ID, TRADE_ID, LOSS_EXE_TYPE, LOSS_GEN_TYPE, CCY, B_CCY, TDY_COST_AMT, TDY_INT_AMT, TDY_LOSSAMT_ADD, TDY_LOSSAMT, TDY_LOSSAMT_ADD_B, TDY_LOSSAMT_B FROM (SELECT rownum AS rn, bp.SEQNO, bp.BOK_SEQNO, bp.BOOKSET_ID, bp.HAPPEN_DATE, bp.BOOK_DATE, bp.BOOKSET_DATE, bp.BOK_DETAIL_ID, bp.BUSI_ID, bp.SCHEME_DETAIL_ID, bp.TRADE_ID, bp.LOSS_EXE_TYPE, bp.LOSS_GEN_TYPE, bp.CCY, bp.B_CCY, bp.TDY_COST_AMT, bp.TDY_INT_AMT, bp.TDY_LOSSAMT_ADD, bp.TDY_LOSSAMT, bp.TDY_LOSSAMT_ADD_B, bp.TDY_LOSSAMT_B FROM BOK_STAT_LOSS_POSIITON bp WHERE 1 =1 AND bp.BOOKSET_ID = #{booksetId}
AND bp.BUSI_ID = #{busiId}
AND bp.HAPPEN_DATE >= #{happenDateSta}
AND bp.HAPPEN_DATE <= #{happenDateEnd}
AND bp.HAPPEN_DATE = #{happenDate}
AND bp.BOOK_DATE <= #{bookDate}
AND bc.BOK_DETAIL_ID = #{bokDetailId}
AND bc.LOSS_GEN_TYPE = #{lossGenType}
ORDER BY HAPPEN_DATE) b WHERE RN =1

    	        SELECT 
					ECL_VAULE 
				FROM 
					TRD_ASSET_LOSS
				WHERE
					VAL_DATE  <=  #{HAPPEN_DATE} 
					AND STATUS = #{TRADE_STATUS_01}
					AND STAGE =  #{stageP3}
					AND SEC_ID = #{secId}
				ORDER by VAL_DATE DESC
